// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint256[] memory v) public {
        vm.assume(_tos.length > 0 && _tos.length == v.length);
        // Bound each v[i] to avoid overflow when multiplied by 1e18
        for (uint i = 0; i < v.length; i++) {
            v[i] = bound(v[i], 0, type(uint256).max / 1e18);
        }
        // The correct caller
        address authorized = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.prank(authorized);
        bool success;
        // The reference C should not revert
        (success, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, _tos, v));
        assertTrue(success, "Reference C should not revert when called by authorized sender");
    }
}

